import { useEffect, useState } from 'react';
import { motion } from 'motion/react';

export default function Header() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ease-out ${
        scrolled
          ? 'bg-background/95 backdrop-blur-sm border-b border-border'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-6xl mx-auto px-6 md:px-12 flex items-center justify-between h-16 md:h-20">
        {/* Logo */}
        <a href="/" aria-label="Alex Morgan — home">
          <img
            src="/airo-assets/images/logo/horizontal"
            alt="Alex Morgan"
            className="h-7 md:h-8 w-auto object-contain shrink-0 self-center"
          />
        </a>

        {/* Nav */}
        <nav aria-label="Main navigation">
          <ul className="flex items-center gap-8 md:gap-10">
            {[
              { label: 'About', href: '#about' },
              { label: 'Contact', href: '#contact' },
            ].map(({ label, href }) => (
              <li key={label}>
                <a
                  href={href}
                  className="relative text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors duration-200 ease-out group"
                >
                  {label}
                  <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-primary transition-all duration-200 ease-out group-hover:w-full" />
                </a>
              </li>
            ))}
          </ul>
        </nav>
      </div>
    </header>
  );
}

export default function Footer() {
  const year = new Date().getFullYear();

  return (
    <footer className="border-t border-border">
      <div className="max-w-6xl mx-auto px-6 md:px-12 py-6 flex items-center justify-between">
        <p className="text-xs text-muted-foreground tracking-wide">
          © {year} Alex Morgan. All rights reserved.
        </p>
        <a
          href="#top"
          className="text-xs text-muted-foreground hover:text-foreground tracking-widest uppercase transition-colors duration-200 ease-out"
        >
          Back to top ↑
        </a>
      </div>
    </footer>
  );
}

