import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter } from 'lucide-react';

// ─── Animation Variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.55, ease: 'easeOut' as const, delay },
  }),
};

const fadeIn = {
  hidden: { opacity: 0, y: 16 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: 'easeOut' as const },
  },
};

// ─── Social Link ──────────────────────────────────────────────────────────────

function SocialLink({
  href,
  label,
  icon: Icon,
}: {
  href: string;
  label: string;
  icon: React.ElementType;
}) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={label}
      className="group flex items-center gap-2 text-muted-foreground hover:text-foreground transition-colors duration-200 ease-out"
    >
      <Icon size={18} strokeWidth={1.5} />
      <span className="relative text-sm tracking-wide">
        {label}
        <span className="absolute -bottom-px left-0 w-0 h-px bg-primary transition-all duration-200 ease-out group-hover:w-full" />
      </span>
    </a>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function HomePage() {
  return (
    <>
      <Helmet>
        <title>Alex Morgan — Designer & Developer</title>
        <meta
          name="description"
          content="Alex Morgan is a designer and developer crafting thoughtful digital experiences at the intersection of design and engineering."
        />
      </Helmet>

      {/* ── Hero ─────────────────────────────────────────────────────────── */}
      <section
        id="top"
        className="relative min-h-screen flex flex-col justify-center px-6 md:px-12 max-w-6xl mx-auto"
        aria-label="Introduction"
      >
        {/* Subtle top rule */}
        <div className="absolute top-0 left-6 right-6 md:left-12 md:right-12 h-px bg-border" />

        <div className="pt-24 pb-16">
          {/* Eyebrow */}
          <motion.p
            className="text-xs tracking-[0.25em] uppercase text-muted-foreground mb-6"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0}
          >
            Portfolio
          </motion.p>

          {/* Name — fluid oversized display */}
          <motion.h1
            className="font-heading font-black leading-[0.9] tracking-tight text-foreground mb-8"
            style={{
              fontSize: 'clamp(4.5rem, 12vw, 11rem)',
            }}
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.1}
          >
            Alex
            <br />
            <span className="text-primary">Morgan</span>
          </motion.h1>

          {/* Tagline */}
          <motion.p
            className="text-lg md:text-xl text-muted-foreground max-w-md leading-relaxed"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.25}
          >
            Designer &amp; Developer crafting thoughtful
            <br className="hidden md:block" /> digital experiences.
          </motion.p>

          {/* CTA */}
          <motion.div
            className="mt-10"
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.38}
          >
            <a
              href="#about"
              className="group inline-flex items-center gap-3 text-sm tracking-widest uppercase text-foreground hover:text-primary transition-colors duration-200 ease-out"
            >
              <span className="w-10 h-px bg-foreground group-hover:bg-primary transition-colors duration-200 ease-out" />
              Learn more
            </a>
          </motion.div>
        </div>

        {/* Scroll indicator */}
        <motion.div
          className="absolute bottom-10 left-6 md:left-12 flex items-center gap-3"
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          custom={0.55}
        >
          <motion.div
            className="w-px h-12 bg-border origin-top"
            animate={{ scaleY: [1, 0.4, 1] }}
            transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' }}
          />
          <span className="text-xs tracking-[0.2em] uppercase text-muted-foreground">
            Scroll
          </span>
        </motion.div>
      </section>

      {/* ── About ────────────────────────────────────────────────────────── */}
      <section
        id="about"
        className="border-t border-border py-24 md:py-36 px-6 md:px-12 max-w-6xl mx-auto"
        aria-label="About"
      >
        <motion.div
          className="grid grid-cols-1 md:grid-cols-[1fr_2fr] gap-12 md:gap-20 items-start"
          variants={fadeIn}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: '-80px' }}
        >
          {/* Left label */}
          <div>
            <p className="text-xs tracking-[0.25em] uppercase text-muted-foreground mb-3">
              About
            </p>
            <h2 className="font-heading font-bold text-3xl md:text-4xl leading-tight text-foreground">
              Background
            </h2>
          </div>

          {/* Right content */}
          <div className="space-y-6">
            <p className="text-base md:text-lg text-muted-foreground leading-relaxed">
              Based in San Francisco, I build products at the intersection of
              design and engineering. With 5+ years of experience across
              startups and agencies, I care deeply about craft, clarity, and
              the details that make digital experiences feel human.
            </p>
            <p className="text-base md:text-lg text-muted-foreground leading-relaxed">
              My work spans product design, front-end development, and design
              systems — always with an eye toward simplicity and intentionality.
            </p>

            {/* Skills row */}
            <div className="pt-4 flex flex-wrap gap-3">
              {['Design Systems', 'React', 'TypeScript', 'Figma', 'Motion'].map(
                (skill) => (
                  <span
                    key={skill}
                    className="text-xs tracking-widest uppercase border border-border px-3 py-1.5 text-muted-foreground"
                  >
                    {skill}
                  </span>
                )
              )}
            </div>
          </div>
        </motion.div>
      </section>

      {/* ── Contact ──────────────────────────────────────────────────────── */}
      <section
        id="contact"
        className="border-t border-border py-24 md:py-36 px-6 md:px-12 max-w-6xl mx-auto"
        aria-label="Contact"
      >
        <motion.div
          className="grid grid-cols-1 md:grid-cols-[1fr_2fr] gap-12 md:gap-20 items-start"
          variants={fadeIn}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: '-80px' }}
        >
          {/* Left label */}
          <div>
            <p className="text-xs tracking-[0.25em] uppercase text-muted-foreground mb-3">
              Contact
            </p>
            <h2 className="font-heading font-bold text-3xl md:text-4xl leading-tight text-foreground">
              Get in touch
            </h2>
          </div>

          {/* Right content */}
          <div className="space-y-10">
            <p className="text-base md:text-lg text-muted-foreground leading-relaxed max-w-md">
              I'm always open to interesting projects and conversations. Feel
              free to reach out.
            </p>

            {/* Email */}
            <div>
              <p className="text-xs tracking-[0.2em] uppercase text-muted-foreground mb-3">
                Email
              </p>
              <a
                href="mailto:hello@alexmorgan.com"
                className="group relative inline-block font-heading font-bold text-2xl md:text-3xl text-foreground hover:text-primary transition-colors duration-200 ease-out"
              >
                hello@alexmorgan.com
                <span className="absolute -bottom-1 left-0 w-0 h-px bg-primary transition-all duration-200 ease-out group-hover:w-full" />
              </a>
            </div>

            {/* Socials */}
            <div>
              <p className="text-xs tracking-[0.2em] uppercase text-muted-foreground mb-4">
                Elsewhere
              </p>
              <div className="flex flex-wrap gap-6">
                <SocialLink
                  href="https://github.com"
                  label="GitHub"
                  icon={Github}
                />
                <SocialLink
                  href="https://linkedin.com"
                  label="LinkedIn"
                  icon={Linkedin}
                />
                <SocialLink
                  href="https://twitter.com"
                  label="Twitter / X"
                  icon={Twitter}
                />
              </div>
            </div>
          </div>
        </motion.div>
      </section>
    </>
  );
}
